<script setup>
import MButton from '../../../components/mds/MButton.vue'; import MEmptyState from '../../../components/mds/MEmptyState.vue'; import MTag from '../../../components/mds/MTag.vue';
defineProps({ rows: { type: Array, default: () => [] }, unread: { type: Number, default: 0 }, canAck: Boolean, working: Boolean, error: { type: String, default: '' } }); const emit = defineEmits(['back', 'read', 'read-all']);
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><div class="mx-auto max-w-[840px] rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]"><header class="flex flex-wrap items-start justify-between gap-3 border-b border-[var(--mds-border-light)] px-5 py-4"><div><h1 class="text-[20px] font-semibold">Hộp thư nhắc</h1><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">{{ unread ? `${unread} thông báo chưa đọc` : 'Không có thông báo chưa đọc' }}</p></div><div class="flex gap-2"><MButton variant="neutral" :disabled="working" @click="emit('back')">Quay lại lịch nhắc</MButton><MButton v-if="canAck && unread" variant="primary" :loading="working" @click="emit('read-all')">Đánh dấu đã đọc</MButton></div></header><p v-if="error" class="mx-5 mt-4 rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{ error }}</p><div v-if="rows.length" class="divide-y divide-[var(--mds-border-light)]"><article v-for="row in rows" :key="row.id" class="flex items-start gap-3 px-5 py-4" :class="row.read ? '' : 'bg-[var(--mds-brand-50)]'"><span class="mt-1 h-2 w-2 shrink-0 rounded-full" :class="row.read ? 'bg-transparent' : 'bg-[var(--mds-brand-600)]'"></span><div class="min-w-0 flex-1"><div class="flex flex-wrap items-start justify-between gap-2"><strong class="text-[14px] leading-5">{{ row.title }}</strong><MTag :color="row.read ? 'neutral' : 'brand'">{{ row.read ? 'Đã đọc' : 'Mới' }}</MTag></div><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">{{ row.occurDate }}<span v-if="row.subjectName"> · {{ row.subjectName }}</span></p><p v-if="row.note" class="mt-2 text-[13px] leading-[18px]">{{ row.note }}</p><MButton v-if="canAck && !row.read" variant="link" class="mt-2" :disabled="working" @click="emit('read', row)">Đánh dấu đã đọc</MButton></div></article></div><MEmptyState v-else title="Chưa có thông báo nhắc" description="Thông báo mới sẽ xuất hiện khi đến lịch nhắc." /></div></section></template>
